-- This entire block is Atomic and Durable once committed
BEGIN;

UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;

-- If either UPDATE fails, the whole transaction rolls back
COMMIT;

const session = client.startSession();

try {
  session.startTransaction();

  await accounts.updateOne(
    { _id: 1 },
    { $inc: { balance: -500 } },
    { session }
  );
  await accounts.updateOne(
    { _id: 2 },
    { $inc: { balance: 500 } },
    { session }
  );

  await session.commitTransaction();
} catch (err) {
  await session.abortTransaction();
} finally {
  session.endSession();
}

// Strong consistency: wait for majority of replica set to acknowledge
db.orders.insertOne(
  { customer: "Aman", total: 1200 },
  { writeConcern: { w: "majority" } }
);

// Read from primary only — strongest read guarantee
db.orders.find().readPref("primary");

// Read from any replica — faster, may be slightly stale
db.orders.find().readPref("secondaryPreferred");

CREATE TABLE users (
    id    SERIAL PRIMARY KEY,
    name  VARCHAR(100) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL
);

CREATE TABLE orders (
    id      SERIAL PRIMARY KEY,
    user_id INT REFERENCES users(id),
    total   NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT now()
);

CREATE TABLE order_items (
    id       SERIAL PRIMARY KEY,
    order_id INT REFERENCES orders(id),
    product  VARCHAR(150),
    qty      INT
);

