CREATE TABLE orders (
    id INT,
    created_at DATE NOT NULL,
    total NUMERIC(10,2)
) PARTITION BY RANGE (created_at);

CREATE TABLE orders_2026_q1 PARTITION OF orders
    FOR VALUES FROM ('2026-01-01') TO ('2026-04-01');

CREATE TABLE orders_2026_q2 PARTITION OF orders
    FOR VALUES FROM ('2026-04-01') TO ('2026-07-01');

sh.enableSharding("ecommerce");

sh.shardCollection(
  "ecommerce.orders",
  { user_id: "hashed" }
);

// Single read returns everything
db.users.findOne({ _id: "u101" });

// Result already contains nested orders array — no second query

// orders collection stores user_id as a reference, not embedded
db.orders.aggregate([
  { $match: { user_id: "u101" } },
  {
    $lookup: {
      from: "users",
      localField: "user_id",
      foreignField: "_id",
      as: "user"
    }
  }
]);

BEGIN;

INSERT INTO orders (user_id, total) VALUES (1, 1200);

-- SAVEPOINT lets you roll back part of a transaction
SAVEPOINT before_items;

INSERT INTO order_items (order_id, product, qty)
VALUES (currval('orders_id_seq'), 'Keyboard', 1);

-- If something goes wrong here:
ROLLBACK TO before_items;

COMMIT;

