rs.initiate({
  _id: "rs0",
  members: [
    { _id: 0, host: "mongo1:27017" },
    { _id: 1, host: "mongo2:27017" },
    { _id: 2, host: "mongo3:27017" }
  ]
});

// Check status and current primary
rs.status();

sh.enableSharding("ecommerce");

// Hashed shard key spreads writes evenly across shards
sh.shardCollection(
  "ecommerce.orders",
  { user_id: "hashed" }
);

// Range-based shard key — good for range queries
sh.shardCollection(
  "ecommerce.events",
  { created_at: 1 }
);

CREATE EXTENSION citus;

-- Mark a table as distributed across worker nodes
SELECT create_distributed_table('orders', 'user_id');

-- Add a worker node to the cluster
SELECT citus_add_node('worker1.db.internal', 5432);

db.createCollection("products", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["name", "price", "category"],
      properties: {
        name:  { bsonType: "string" },
        price: { bsonType: "number", minimum: 0 },
        category: {
          enum: ["electronics", "clothing", "books"]
        }
      }
    }
  }
});
